import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Teorema di Rolle","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/c_analisi/cf/cfea.md","filePath":"lezioni/c_analisi/cf/cfea.md"}`),a={name:`lezioni/c_analisi/cf/cfea.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="teorema-di-rolle" tabindex="-1">Teorema di Rolle <a class="header-anchor" href="#teorema-di-rolle" aria-label="Permalink to “Teorema di Rolle”">​</a></h1><p>Questo teorema afferma che se una funzione è continua in un intervallo chiuso e limitato e derivabile all&#39;interno dell&#39;intervallo stesso e se inoltre agli estremi dell&#39;intervallo assume lo stesso valore allora esiste almeno un punto dell&#39;intervallo in cui la derivata della funzione vale <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>0</mn></mrow><annotation encoding="application/x-tex">0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span>.</p><p>Come si vede dalla figura in pratica vuol dire che se la funzione parte da un certo valore ed arriva allo stesso valore senza fare punte allora se è continua e se l&#39;intervallo è chiuso e limitato ci deve essere un punto dove finisce di crescere (o di diminuire) e torna indietro (si può anche dire che la tangente in quel punto è orizzontale).</p><p>Matematicamente:</p><p>se <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="red"><mi>y</mi><mo>=</mo><mi>f</mi><mo stretchy="false">(</mo><mi>x</mi><mo stretchy="false">)</mo></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{y=f(x)}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;color:red;">y</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1076em;color:red;">f</span><span class="mopen" style="color:red;">(</span><span class="mord mathnormal" style="color:red;">x</span><span class="mclose" style="color:red;">)</span></span></span></span> è una funzione continua in un intervallo chiuso e limitato <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="red"><mo stretchy="false">[</mo><mi>a</mi><mo separator="true">,</mo><mi>b</mi><mo stretchy="false">]</mo></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{[a, b]}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen" style="color:red;">[</span><span class="mord mathnormal" style="color:red;">a</span><span class="mpunct" style="color:red;">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="color:red;">b</span><span class="mclose" style="color:red;">]</span></span></span></span> e tale che <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="red"><mi>f</mi><mo stretchy="false">(</mo><mi>a</mi><mo stretchy="false">)</mo><mo>=</mo><mi>f</mi><mo stretchy="false">(</mo><mi>b</mi><mo stretchy="false">)</mo></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{f(a) = f(b)}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1076em;color:red;">f</span><span class="mopen" style="color:red;">(</span><span class="mord mathnormal" style="color:red;">a</span><span class="mclose" style="color:red;">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1076em;color:red;">f</span><span class="mopen" style="color:red;">(</span><span class="mord mathnormal" style="color:red;">b</span><span class="mclose" style="color:red;">)</span></span></span></span> allora esiste un punto <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="red"><mi>c</mi></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{c}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="color:red;">c</span></span></span></span> appartenente ad <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="red"><mo stretchy="false">[</mo><mi>a</mi><mo separator="true">,</mo><mi>b</mi><mo stretchy="false">]</mo></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{[a, b]}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen" style="color:red;">[</span><span class="mord mathnormal" style="color:red;">a</span><span class="mpunct" style="color:red;">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="color:red;">b</span><span class="mclose" style="color:red;">]</span></span></span></span> tale che <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="red"><msup><mi>f</mi><mo mathvariant="normal" lspace="0em" rspace="0em">′</mo></msup><mo stretchy="false">(</mo><mi>c</mi><mo stretchy="false">)</mo><mo>=</mo><mn>0</mn></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{f&#39;(c)=0}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1.0019em;vertical-align:-0.25em;"></span><span class="mord" style="color:red;"><span class="mord mathnormal" style="margin-right:0.1076em;color:red;">f</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight" style="color:red;"><span class="mord mtight" style="color:red;"><span class="mord mtight" style="color:red;">′</span></span></span></span></span></span></span></span></span><span class="mopen" style="color:red;">(</span><span class="mord mathnormal" style="color:red;">c</span><span class="mclose" style="color:red;">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord" style="color:red;">0</span></span></span></span></p><hr><p>L&#39;utilizzo di questo teorema in tante verifiche sia orali che scritte risiede nel fatto che deve verificare quattro ipotesi:</p><ol><li>che la funzione sia continua</li><li>che la funzione sia derivabile all&#39;interno dell&#39;intervallo</li><li>che l&#39;intervallo sia chiuso e limitato</li><li>che i valori agli estremi dell&#39;intervallo siano uguali</li></ol><blockquote><p>ora prova a dimostrare che il teorema non è verificato (cioè fai un esempio in cui il teorema non sia valido) se manca la prima ipotesi, oppure la terza, oppure la seconda e la terza...</p><p>capisci che per risolverlo sei costretto a ragionare ed a sapere esattamente cosa si intende per funzione continua, per intervallo chiuso per intervallo limitato eccetera.</p><p>Dopo aver provato da solo confronta con <a href="./cfea1.html">questi esempi</a> piuttosto alla buona e che non comprendono certo tutti i casi possibili</p></blockquote>`,9)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};